/**
 * OS convergence executor for ROUTING (static routes + PBR policy rules).
 *
 * Mirrors iface-apply.ts guards, with route-specific protection semantics:
 *
 *   gate        CONSOLE_OS_APPLY=1            off → plan preview, no exec
 *   tool        `ip` (iproute2) on the host
 *   whitelist   only `ip route|ip rule` verbs generated by the planners
 *   protect     routes and policy rules never change interface state or
 *               addresses, so egress `dev ens32` (WAN) is legitimate here.
 *               The guard therefore refuses only `dev lo` loopback installs
 *               and keeps the metric-≥1 default-hijack guarantee from the
 *               planner (interface-managed metric-0 default always wins).
 */

import { hasTool, runTool } from "@/lib/host/tools";
import type { OsPlan } from "./route-os";

export interface OsStepResult {
  cmd: string;
  ok: boolean;
  stderr?: string;
}

export interface OsApplyOutcome {
  gate: "on" | "off";
  applied: boolean;
  reason: string;
  plan: OsPlan;
  results?: OsStepResult[];
}

const ROUTE_EXEC_WHITELIST =
  /^ip (route (replace|del|add|flush)|rule (add|del)) [a-z0-9].*$/;

function execGuard(plan: OsPlan): OsApplyOutcome | null {
  if (process.env.CONSOLE_OS_APPLY !== "1") {
    return {
      gate: "off",
      applied: false,
      reason: "OS convergence is disabled by platform policy on this installation — the plan above is a preview only",
      plan,
    };
  }
  return null;
}

async function execPlan(plan: OsPlan): Promise<OsApplyOutcome> {
  const guarded = execGuard(plan);
  if (guarded) return guarded;
  if (!(await hasTool("ip"))) {
    return { gate: "on", applied: false, reason: "'ip' (iproute2) not found on the host — cannot execute the plan", plan };
  }

  for (const step of plan.steps) {
    if (!ROUTE_EXEC_WHITELIST.test(step.cmd)) {
      return { gate: "on", applied: false, reason: "refused: plan step failed the iproute2 whitelist — execution aborted", plan };
    }
    // loopback is never a valid static-route egress or policy-table device
    if (/(^|\s)dev lo(\s|$)/.test(step.cmd)) {
      return { gate: "on", applied: false, reason: "refused: step installs via loopback (management guard)", plan };
    }
  }

  const results: OsStepResult[] = [];
  for (const step of plan.steps) {
    const r = await runTool(step.cmd);
    results.push({ cmd: step.cmd, ok: r.ok, stderr: r.ok ? undefined : r.stderr || r.error });
    if (!r.ok) break; // transactional: stop at first failure
  }
  const failed = results.filter((r) => !r.ok);
  return {
    gate: "on",
    applied: failed.length === 0,
    reason: failed.length === 0 ? "applied to host" : `${failed.length} step(s) failed`,
    plan,
    results,
  };
}

const failOutcome = (reason: string, plan: OsPlan): OsApplyOutcome => ({
  gate: process.env.CONSOLE_OS_APPLY === "1" ? "on" : "off",
  applied: false,
  reason,
  plan,
});

/** Never throws — convergence errors surface as an honest failed outcome. */
export async function convergeRouteSafe(build: () => Promise<OsPlan>): Promise<OsApplyOutcome> {
  try {
    return await execPlan(await build());
  } catch (err) {
    return failOutcome(`convergence error: ${err instanceof Error ? err.message : "unknown"}`, {
      name: "?",
      osName: null,
      steps: [],
    });
  }
}
